head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getComponentById]<br/>ID 를 사용하여 WebSquare 컴포넌트 객체를 반환합니다.",
    "validation" : [
        "id(필수) 파라미터로 조회할 컴포넌트의 ID 를 설정할 수 있어야 합니다.",
        "id 에 해당하는 WebSquare 컴포넌트 객체를 반환해야 합니다.",
        "id 에 해당하는 컴포넌트가 없으면 undefined 를 반환해야 합니다.",
    ]
}



scwin.compIds = ["target_textbox", "target_button", "target_input", "target_calendar", "target_checkbox", "target_selectbox", "target_group", "target_gridview"];

scwin.comp_init = async function () {
    for (var i = 0; i < scwin.compIds.length; i++) {
        try { if (typeof window[scwin.compIds[i]] !== "undefined") { window[scwin.compIds[i]].remove(); } } catch(e) {}
    }

    var ns = $c.gcm.getNameSpace();
    var grp_comp = $c.gcm.getTestGroup();

    var strTxt = '<w2:textbox ' + ns + ' label="target_textbox" style="width:150px;"></w2:textbox>';
    await $p.dynamicCreate("target_textbox", "textbox", strTxt, grp_comp);

    var strBtn = '<w2:button ' + ns + ' label="target_button" class="tc_btn_basic" style=""></w2:button>';
    await $p.dynamicCreate("target_button", "button", strBtn, grp_comp);

    var strInput = '<xf:input ' + ns + ' id="target_input" style="width:150px;" placeholder="target_input"></xf:input>';
    await $p.dynamicCreate("target_input", "input", strInput, grp_comp);

    var strCalendar = '<w2:calendar ' + ns + ' id="target_calendar" style="width:150px;"></w2:calendar>';
    await $p.dynamicCreate("target_calendar", "calendar", strCalendar, grp_comp);

    var strCheckbox = '<w2:checkbox ' + ns + ' id="target_checkbox" label="target_checkbox" style=""></w2:checkbox>';
    await $p.dynamicCreate("target_checkbox", "checkbox", strCheckbox, grp_comp);

    var strSelect = '<xf:select1 ' + ns + ' appearance="minimal" id="target_selectbox" style="width:150px;">'
        + '<xf:choices><xf:item><xf:label>항목1</xf:label><xf:value>1</xf:value></xf:item>'
        + '<xf:item><xf:label>항목2</xf:label><xf:value>2</xf:value></xf:item></xf:choices>'
        + '</xf:select1>';
    await $p.dynamicCreate("target_selectbox", "selectbox", strSelect, grp_comp);

    var strGroup = '<xf:group ' + ns + ' id="target_group" style="padding:5px; border:1px solid #ccc; display:inline-block;"><w2:textbox ' + ns + ' label="group 내부" style=""></w2:textbox></xf:group>';
    await $p.dynamicCreate("target_group", "group", strGroup, grp_comp);

    var strGrid = '<w2:gridView ' + ns + ' id="target_gridview" style="width:300px; height:100px;"></w2:gridView>';
    await $p.dynamicCreate("target_gridview", "gridView", strGrid, grp_comp);
}



scwin.onpageload = async function () {
    $c.gcm.createCommonDatalist();
    await scwin.comp_init();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getComponentById_onclick = function () {
    var id = par_id.getValue();

    var comp = $p.getComponentById(id);

    if (comp !== undefined) {
        var result = [];
        result.push("반환 타입 : " + typeof comp);
        result.push("컴포넌트 ID : " + (comp.id || "N/A"));
        wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("반환값 : undefined (컴포넌트 없음)");
    }
}
